const listSessions = `-- name: ListSessions :many
SELECT s.id, s.user_id, s.device_id, s.token_hash, s.credential_kind,
    s.temporary_password_id, s.last_ip, s.user_agent, s.last_seen_at,
    s.expires_at, s.revoked_at, s.created_at, s.updated_at, s.version,
    u.username::text AS username, d.name AS device_name
FROM sessions s
JOIN users u ON u.id = s.user_id AND u.deleted_at IS NULL
JOIN devices d ON d.id = s.device_id AND d.user_id = s.user_id
WHERE s.revoked_at IS NULL AND s.expires_at > now()
  AND ($1::uuid IS NULL OR s.user_id = $1::uuid)
ORDER BY s.last_seen_at DESC
`

type ListSessionsRow struct {
	ID                  pgtype.UUID        `json:"id"`
	UserID              pgtype.UUID        `json:"user_id"`
	DeviceID            pgtype.UUID        `json:"device_id"`
	TokenHash           []byte             `json:"token_hash"`
	CredentialKind      string             `json:"credential_kind"`
	TemporaryPasswordID pgtype.UUID        `json:"temporary_password_id"`
	LastIp              *netip.Addr        `json:"last_ip"`
	UserAgent           string             `json:"user_agent"`
	LastSeenAt          pgtype.Timestamptz `json:"last_seen_at"`
	ExpiresAt           pgtype.Timestamptz `json:"expires_at"`
	RevokedAt           pgtype.Timestamptz `json:"revoked_at"`
	CreatedAt           pgtype.Timestamptz `json:"created_at"`
	UpdatedAt           pgtype.Timestamptz `json:"updated_at"`
	Version             int64              `json:"version"`
	Username            string             `json:"username"`
	DeviceName          string             `json:"device_name"`
}

func (q *Queries) ListSessions(ctx context.Context, userID pgtype.UUID) ([]ListSessionsRow, error) {
	rows, err := q.db.Query(ctx, listSessions, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListSessionsRow{}
	for rows.Next() {
		var i ListSessionsRow
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.DeviceID,
			&i.TokenHash,
			&i.CredentialKind,
			&i.TemporaryPasswordID,
			&i.LastIp,
			&i.UserAgent,
			&i.LastSeenAt,
			&i.ExpiresAt,
			&i.RevokedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Version,
			&i.Username,
			&i.DeviceName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

